"""Framework-free Media Lab Manager HTTP API and static-file server."""

from __future__ import annotations

import hashlib
import hmac
import http.server
import json
import os
import secrets
import sys
import time
from http import HTTPStatus
from pathlib import Path
from urllib.parse import parse_qs, unquote, urlparse

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "MLM.Database"))
from mlm_database_commands import Database  # noqa: E402


FRONTEND = ROOT / "Media Lab Front"
PORT = int(os.environ.get("PORT", "3000"))
SESSION_SECONDS = 8 * 60 * 60
SESSIONS: dict[str, tuple[float, dict]] = {}
db = Database()


def json_text(value) -> bytes:
    return json.dumps(value, separators=(",", ":")).encode("utf-8")


def hash_pin(pin: str) -> str:
    salt = secrets.token_bytes(16)
    digest = hashlib.scrypt(pin.encode(), salt=salt, n=16384, r=8, p=1, dklen=32)
    return f"scrypt${salt.hex()}${digest.hex()}"


def verify_pin(pin: str, encoded: str) -> bool:
    try:
        scheme, salt_hex, digest_hex = encoded.split("$")
        if scheme != "scrypt":
            return False
        actual = hashlib.scrypt(pin.encode(), salt=bytes.fromhex(salt_hex), n=16384, r=8, p=1, dklen=32)
        return hmac.compare_digest(actual, bytes.fromhex(digest_hex))
    except (ValueError, TypeError):
        return False


def public_user(user: dict, account_type: str | None = None) -> dict:
    return {"id": user["id"], "kreaId": user["krea_id"], "name": user["name"],
            "email": user.get("email"), "role": account_type or user.get("role")}


def request_view(request_id: int):
    return db._request_view(request_id)


def all_requests(filters: dict):
    clauses, values = [], []
    if filters.get("requesterId"):
        clauses.append("r.requester_id=?")
        values.append(int(filters["requesterId"]))
    if filters.get("status"):
        clauses.append("r.status=?")
        values.append(filters["status"])
    where = " WHERE " + " AND ".join(clauses) if clauses else ""
    rows = db.connection.execute(
        "SELECT r.id FROM requests r JOIN users u ON u.id=r.requester_id" + where +
        " ORDER BY r.created_at DESC", values).fetchall()
    return [request_view(row["id"]) for row in rows]


def parse_json(handler):
    length = int(handler.headers.get("Content-Length", "0"))
    if length > 1024 * 1024:
        raise ValueError("Request body is too large")
    raw = handler.rfile.read(length)
    if not raw:
        return {}
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as error:
        raise ValueError("Invalid JSON") from error
    if not isinstance(value, dict):
        raise ValueError("JSON body must be an object")
    return value


class ApiError(Exception):
    def __init__(self, message: str, status: int = 400):
        super().__init__(message)
        self.status = status


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "MediaLabManager/1.0"

    def log_message(self, format, *args):
        print(f"{self.address_string()} - {format % args}")

    def send_json(self, status: int, value, extra_headers=None):
        body = json_text(value)
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Cache-Control", "no-store")
        for name, value in (extra_headers or {}).items():
            self.send_header(name, value)
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, error):
        status = error.status if isinstance(error, ApiError) else 500
        self.send_json(status, {"error": str(error)})

    def cookies(self):
        result = {}
        for part in self.headers.get("Cookie", "").split(";"):
            if "=" in part:
                key, value = part.strip().split("=", 1)
                result[key] = value
        return result

    def current_user(self):
        authorization = self.headers.get("Authorization", "")
        token = authorization[7:].strip() if authorization.startswith("Bearer ") else ""
        token = token or self.cookies().get("mlm_session")
        session = SESSIONS.get(token)
        if not session:
            return None
        expires, user = session
        if expires < time.time():
            SESSIONS.pop(token, None)
            return None
        SESSIONS[token] = (time.time() + SESSION_SECONDS, user)
        return user

    def require_user(self):
        user = self.current_user()
        if not user:
            raise ApiError("You must sign in first.", 401)
        return user

    def require_staff(self):
        user = self.require_user()
        if user.get("role") not in {"faculty", "media_lab", "admin", "staff"}:
            raise ApiError("Staff access is required.", 403)
        return user

    def do_OPTIONS(self):
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", self.headers.get("Origin", "*"))
        self.send_header("Access-Control-Allow-Credentials", "true")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, Authorization")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
        self.end_headers()

    def do_GET(self):
        try:
            parsed = urlparse(self.path)
            if parsed.path.startswith("/api/"):
                self.api("GET", parsed.path, parse_qs(parsed.query))
            else:
                self.static_file(parsed.path)
        except Exception as error:
            self.send_error_json(error)

    def do_POST(self):
        try:
            parsed = urlparse(self.path)
            if not parsed.path.startswith("/api/"):
                raise ApiError("Route not found.", 404)
            self.api("POST", parsed.path, parse_json(self))
        except Exception as error:
            self.send_error_json(error)

    def api(self, method, path, query_or_body):
        if method == "POST" and path == "/api/auth/login":
            body = query_or_body
            account = str(body.get("accountType", "")).strip().lower()
            email = str(body.get("email", "")).strip().lower()
            pin = str(body.get("pin", ""))
            if account not in {"student", "faculty", "media_lab"}:
                raise ApiError("Choose Student, Faculty, or Media Lab.")
            domain = "@krea.ac.in" if account == "student" else "@krea.edu.in"
            if not email.endswith(domain):
                raise ApiError(f"This account must use {domain}.")
            if not pin.isdigit() or len(pin) != 4:
                raise ApiError("PIN must be exactly 4 digits.")
            row = db.connection.execute("SELECT * FROM users WHERE email=? LIMIT 1", (email,)).fetchone()
            user = dict(row) if row else None
            if user is None:
                user = db.add_user({"kreaId": email, "name": email.split("@", 1)[0], "email": email,
                                    "role": account, "pinHash": hash_pin(pin)})
            elif not user.get("pin_hash") or not verify_pin(pin, user["pin_hash"]):
                raise ApiError("Invalid email or PIN.")
            if user.get("banned"):
                raise ApiError("This account is banned.")
            safe = public_user(user, account)
            token = secrets.token_hex(32)
            SESSIONS[token] = (time.time() + SESSION_SECONDS, safe)
            headers = {"Set-Cookie": f"mlm_session={token}; HttpOnly; SameSite=Lax; Path=/; Max-Age={SESSION_SECONDS}"}
            return self.send_json(200, {"user": safe, "sessionToken": token}, headers)

        if method == "POST" and path == "/api/auth/logout":
            token = self.headers.get("Authorization", "")[7:].strip() if self.headers.get("Authorization", "").startswith("Bearer ") else self.cookies().get("mlm_session")
            SESSIONS.pop(token, None)
            return self.send_json(200, {"ok": True}, {"Set-Cookie": "mlm_session=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0"})

        if method == "GET" and path == "/api/auth/me":
            user = self.current_user()
            if not user:
                raise ApiError("Not signed in.", 401)
            return self.send_json(200, {"user": user})

        user = self.require_user()
        if method == "GET" and path == "/api/equipment":
            values = {key: items[0] for key, items in query_or_body.items()}
            return self.send_json(200, db.find(values))
        if method == "GET" and path == "/api/equipment/stats":
            return self.send_json(200, db.stats())
        if method == "POST" and path == "/api/users":
            self.require_staff()
            body = query_or_body
            return self.send_json(201, db.add_user(body))
        if method == "POST" and path == "/api/requests":
            body = {**query_or_body, "requesterId": user["id"]}
            return self.send_json(201, db.create_request(body))
        if method == "GET" and path == "/api/requests":
            values = {key: items[0] for key, items in query_or_body.items()}
            if values.get("requesterId") and int(values["requesterId"]) != user["id"]:
                self.require_staff()
            return self.send_json(200, all_requests(values))

        parts = [unquote(part) for part in path.split("/") if part]
        if len(parts) >= 3 and parts[1] == "requests":
            request_id = int(parts[2])
            if parts[3:] and parts[3] == "approve":
                self.require_staff(); body = query_or_body
