  window.mlmApi = {
    base,
    login: body => json('POST', '/auth/login', body).then(data => { if (data.sessionToken) storage.setItem('mlmSessionToken', data.sessionToken); if (data.user) storage.setItem('mlmUser', JSON.stringify(data.user)); return data; }),
